def run(c,root,args):
 c.group='abstractions-session';pub=root/'labs/api_depth/abstractions';private=root/'assessor/api_depth/abstractions';source=private/'session.c';providers=[root/'assessor/api_depth/contracts/ownership.c',root/'assessor/foundations/foundation.c'];common=['-std=c17','-Wall','-Wextra','-Werror','-I'+str(pub),'-I'+str(root/'labs/api_depth/contracts'),'-I'+str(root/'labs/api_depth/include'),'-I'+str(root/'labs/foundations/include')]
 for cc in ('gcc','clang'):
  for name,flags in [('debug',['-O0']),('release',['-O2']),('sanitize',['-O1','-fsanitize=address,undefined','-fno-pie','-no-pie'])]:
   exe=c.root/(cc+'-'+name+'-session');c.run([cc,*common,*flags,pub/'session_tests.c',source,*providers,'-o',exe]);c.run([exe],contains='SESSION-PASS:state_events=384;constructor_callbacks=2;')
