 obj=c.root/'session.o';c.run(['gcc',*common,'-O0','-c',source,'-o',obj]);symbols=c.run(['nm','-u',obj]);c.require('ac_resource_acquire' in symbols and 'ac_resource_close' in symbols,'actual T18 resource ledger imported',symbols)
